import React, { useState, useEffect } from "react";
import "./styles.css";

function App() {
  const [budget, setBudget] = useState("");
  const [predicted, setPredicted] = useState(null);
  const [data, setData] = useState([]);
  const [error, setError] = useState("");

  const handlePredict = async () => {
    if (!budget) {
      setError("Please enter a budget amount");
      return;
    }
    setError("");
    setPredicted(null);
    try {
      const res = await fetch(`http://127.0.0.1:5000/prediction/${budget}`);
      const result = await res.json();
      setPredicted(result);
    } catch {
      setError("Error fetching prediction");
    }
  };

  useEffect(() => {
    const fetchData = async () => {
      try {
        const res = await fetch("http://127.0.0.1:5000/api");
        const raw = await res.json();
        const parsed = typeof raw === "string" ? JSON.parse(raw) : raw;
        setData(parsed);
      } catch {}
    };
    fetchData();
  }, []);

  return (
    <div>
      <nav className="navbar">
        <div className="container">
          <span className="brand">SALES PREDICTION DEMO</span>
        </div>
      </nav>

      <header className="hero">
        <h2>Predict Sales from Budget</h2>
        <div className="form">
          <input
            type="number"
            placeholder="Enter Budget"
            value={budget}
            onChange={(e) => setBudget(e.target.value)}
          />
          <button onClick={handlePredict}>Predict</button>
        </div>
        {error && <p className="error">{error}</p>}
      </header>

      <section className="results">
        <div className="card">
          <h5>Budget Amount</h5>
          <p>{budget ? `${budget}K` : "-"}</p>
        </div>
        <div className="card">
          <h5>Predicted Value</h5>
          <p>{predicted ? `${predicted}M` : "-"}</p>
        </div>
        <div className="card">
          <h5>API Status</h5>
          <p>{budget ? "Flask API Call" : "-"}</p>
        </div>
      </section>

      <div className="table-container">
        <h4>Data Used for Model</h4>
        <table>
          <thead>
            <tr>
              <th>Budget</th>
              <th>Sales</th>
            </tr>
          </thead>
          <tbody>
            {data.map((row, idx) => (
              <tr key={idx}>
                <td>{row.budget}</td>
                <td>{row.sale}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <footer className="footer">
        <p>© NEHU 2025. All Rights Reserved.</p>
      </footer>
    </div>
  );
}

export default App;
